style.css:
@-moz-document domain("youtube.com") {
/* Hide the current logo icon */
  #logo-icon {
    display: none !important;
  }

  /* Style the logo container to show the classic logo */
  #logo {
    background-image: url('https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/YouTube_icon_2013.svg/2560px-YouTube_icon_2013.svg.png');
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: 120px !important;
    height: 40px !important;
  }

  /* Hide the modern "YouTube" text next to the icon if needed */
  #logo #logo-content {
    opacity: 0 !important;
  }
}
